(5243453, 762553, 95728, '<td valign="top">I like the idea and the way the photo was composed...and nothing sends the message of end better than...CHECKMATE!</td>', 'I like the idea and the way the photo was composed...and nothing sends the message of end better than...CHECKMATE!', '2009-02-07 07:15:25.000000', NULL, 1),
